SELECT tb_q_checks.tdate, tb_q_checks.CDate, tb_q_checks.cnum, tb_q_checks.code_sapak, tb_q_checks.snif, tb_q_checks.qcount, tb_q_checks.CDate AS tpiraon, DateAdd("m",Val(nz([qcount]))-1,[cdate]) AS qdate, tb_q_checks.total, tb_q_checks.hnum4, tb_q_checks.qstatus
FROM tb_q_checks
WHERE (((tb_q_checks.hnum4)="אשראי"));

SELECT tb_credits.cn,null As kamp, tb_credits.namew, tb_credits.ordernum, tb_credits.typ, tb_credits.tpiraon, tb_credits.total, tb_credits.qtotal, tb_credits.qpay, tb_credits.qpayn
FROM tb_credits;
UNION ALL SELECT orders.cn, cust_list.kamp,Trim$([fname])+"  "+Trim$([pname]) AS namew, orders.ordernum, tb_kabala.typ, tb_kabala.tpiraon, tb_kabala.total,null ,null  ,null 
FROM (cust_list INNER JOIN orders ON cust_list.numw = orders.numw) INNER JOIN tb_kabala ON orders.rnum = tb_kabala.rnum
WHERE (((orders.cn)=False) AND ((tb_kabala.typ)<>"אשראי"))
ORDER BY tpiraon;

SELECT tb_credits.cn, tb_credits.namew, tb_credits.ordernum, tb_credits.typ,tb_credits.odate,tb_credits.wdate, tb_credits.tpiraon, tb_credits.total, tb_credits.qtotal, tb_credits.qpay, tb_credits.qpayn
FROM tb_credits;
UNION ALL SELECT orders.cn, Trim$([fname])+"  "+Trim$([pname]) AS namew, orders.ordernum, tb_kabala.typ, orders.odate, tb_kabala.wdate, tb_kabala.tpiraon, tb_kabala.total,null ,null  ,null 
FROM (cust_list INNER JOIN orders ON cust_list.numw = orders.numw) INNER JOIN tb_kabala ON orders.rnum = tb_kabala.rnum
WHERE (((orders.cn)=False) AND ((tb_kabala.typ)<>"אשראי"))
ORDER BY tpiraon;
